    [Fact]
    public async Task GetAsync_ReturnsRepositoryResult()
    {
        var expected = new ExampleItemModel { Name = "widget" };
        var repository = new FakeExampleItemRepository { GetByNameResult = expected };
        var service = CreateService(repository);

        var result = await service.GetAsync("widget", TestContext.Current.CancellationToken);

        Assert.Same(expected, result);
        Assert.Equal("widget", repository.LastGetByName);
        Assert.Equal(TestContext.Current.CancellationToken, repository.LastGetByNameCancellationToken);
    }

    [Fact]
    public async Task GetListAsync_ReturnsRepositoryResult()
    {
        var expected = new ExampleItemListModel
        {
            ContinuationToken = "next",
            Items = [new ExampleItemModel { Name = "a" }]
        };
        var repository = new FakeExampleItemRepository { GetListResult = expected };
