    [Fact]
    public async Task PutAsync_ReturnsCachedResponse_WithoutCallingRepositoryOrLock()
    {
        var cached = new ExampleItemModel { Name = "cached" };
        var repository = new FakeExampleItemRepository();
        var idempotency = new FakeSubmissionIdempotencyService
        {
            GetRecordResult = cached
        };
        var service = CreateService(repository, idempotency);
        var model = new ExampleItemModel { Name = "fresh" };

        var result = await service.PutAsync(model, "idem-1", TestContext.Current.CancellationToken);

        Assert.Same(cached, result);
        Assert.Equal("idem-1", idempotency.LastGetRecordKey);
        Assert.False(idempotency.GetLockCalled);
        Assert.False(repository.PutCalled);
        Assert.False(idempotency.SetRecordCalled);
    }

    [Fact]
    public async Task PutAsync_ThrowsIdempotentConcurrency_WhenLockIsNotAcquired()
    {
        var repository = new FakeExampleItemRepository();
        var lockHandle = new FakeLock(false);
        var idempotency = new FakeSubmissionIdempotencyService
        {
            GetRecordResult = null,
            LockToReturn = lockHandle
        };
        var service = CreateService(repository, idempotency);

        await Assert.ThrowsAsync<IdempotentConcurrencyException>(() =>
            service.PutAsync(new ExampleItemModel { Name = "widget" }, "idem-1",
                TestContext.Current.CancellationToken));

        Assert.True(idempotency.GetLockCalled);
        Assert.Equal("idem-1", idempotency.LastGetLockKey);
        Assert.False(repository.PutCalled);
        Assert.False(lockHandle.UnlockCalled);
    }

