        var lockHandle = new FakeLock(true);
        var idempotency = new FakeSubmissionIdempotencyService
        {
            LockToReturn = lockHandle
        };
        var service = CreateService(repository, idempotency);

        var exception = await Assert.ThrowsAsync<BadRequestException>(() =>
            service.PutAsync(new ExampleItemModel { Name = name! }, "idem-1",
                TestContext.Current.CancellationToken));

        Assert.Equal("Name is required", exception.Message);
        Assert.True(idempotency.GetLockCalled);
        Assert.False(repository.PutCalled);
        Assert.False(idempotency.SetRecordCalled);
