    [Fact]
    public async Task PutAsync_PersistsCachesAndUnlocks_OnSuccess()
    {
        var repository = new FakeExampleItemRepository();
        var lockHandle = new FakeLock(true);
        var idempotency = new FakeSubmissionIdempotencyService
        {
            LockToReturn = lockHandle
        };
        var service = CreateService(repository, idempotency);
        var model = new ExampleItemModel { Name = "widget" };

        var result = await service.PutAsync(model, "idem-1", TestContext.Current.CancellationToken);

        Assert.Same(model, result);
        Assert.Same(model, repository.LastPutModel);
        Assert.Equal(TestContext.Current.CancellationToken, repository.LastPutCancellationToken);
        Assert.Equal("idem-1", idempotency.LastSetRecordKey);
        Assert.Same(model, idempotency.LastSetRecordValue);
        Assert.True(lockHandle.UnlockCalled);
    }

    private static ExampleItemService CreateService(
        IExampleItemRepository? repository = null,
        ISubmissionIdempotencyService? idempotencyService = null)
    {
        return new ExampleItemService(
            repository ?? new FakeExampleItemRepository(),
            idempotencyService ?? new FakeSubmissionIdempotencyService());
    }

