    private sealed class FakeSubmissionIdempotencyService : ISubmissionIdempotencyService
    {
        public object? GetRecordResult { get; init; }
        public IAbstractedLock LockToReturn { get; init; } = new FakeLock(true);

        public string? LastGetRecordKey { get; private set; }
