        }

        public Task<T?> GetRecordAsync<T>(string key, CancellationToken cancellationToken = default)
        {
            LastGetRecordKey = key;
            return Task.FromResult(GetRecordResult is T typed ? typed : default);
        }

        public Task SetRecordAsync<T>(string key, T value, CancellationToken cancellationToken = default)
        {
